steps.run:
set -euo pipefail
psql -h localhost -U postgres -d postgres -v ON_ERROR_STOP=1 <<'SQL'
DO $proof$
DECLARE
  v_constraint text;
BEGIN
  BEGIN
    INSERT INTO public.marketing_campaigns(
      id,account_id,brand_id,audience_id,name,channel,channel_payload,status
    ) VALUES (
      gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),
      'Issue 2393 invalid-payload proof','email','{"kind":"email"}','sending'
    );
    RAISE EXCEPTION '#2393 FAIL: #2291 accepted a bare non-draft email payload';
  EXCEPTION WHEN check_violation THEN
    GET STACKED DIAGNOSTICS v_constraint = CONSTRAINT_NAME;
    IF v_constraint <> 'marketing_campaigns_payload_content_required' THEN
      RAISE;
    END IF;
  END;
END
$proof$;
SQL

